import net.minecraft.resources.ResourceLocation;
final class ReagentRuntime {
 static void run(GameTestHelper h,ServerPlayer p,ConstructionStore.Project lab)throws Exception{new Walk(h,p,lab).start();}
 static final class Walk {
  final GameTestHelper h;final ServerPlayer p;final ServerLevel level;final ConstructionStore.Project lab;final BlockPos plot;final CropBlock crop;final Item seed,essence;final ItemStack original;
  Walk(GameTestHelper h,ServerPlayer p,ConstructionStore.Project lab){this.h=h;this.p=p;this.lab=lab;level=h.getLevel();plot=lab.origin().offset(0,1,35);var block=BuiltInRegistries.BLOCK.get(ResourceLocation.parse(ReagentCropService.CROP));h.assertTrue(ReagentCropService.supported()&&block instanceof CropBlock,"Exact supported8.0.29registered native Inferium crop");crop=(CropBlock)block;seed=BuiltInRegistries.ITEM.get(ResourceLocation.parse("mysticalagriculture:inferium_seeds"));essence=BuiltInRegistries.ITEM.get(ResourceLocation.parse(ReagentCropService.ESSENCE));h.assertTrue(seed!=Items.AIR&&essence!=Items.AIR&&crop.getMaxAge()==7,"Actual native seed/essence identities and age verified");original=p.getMainHandItem().copy();}
  void guard(Runnable action){try{action.run();}catch(Exception e){h.fail(e.toString());}}
  void near(){BlacksmithRepairRuntime.near(p,plot);level.getChunkSource().move(p);}
  ReagentCropProof.Cell cell(){return new ReagentCropProof.Cell(level.dimension().location().toString(),plot.asLong());}
  void start()throws Exception{var track=CommerceService.store(p.server).professions(p.getUUID()).track(Profession.ALCHEMIST);for(int x=(plot.getX()-2)>>4;x<=(plot.getX()+2)>>4;x++)for(int z=(plot.getZ()-2)>>4;z<=(plot.getZ()+2)>>4;z++){var at=new BlockPos(x*16,plot.getY(),z*16);level.getChunk(x,z);ClaimRuntimeTests.ftbUnclaim(level,at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacClaim(level,p.getUUID(),at);}if(track.completedQuestIds().contains(ReagentCropService.QUEST)){h.assertTrue(track.xp()==1800&&track.completedQuestIds().size()==13&&ReagentCropSavedData.get(p.server).proof().count(p.getUUID())>=32,"Actual earned native crop13proofs1800XPrestore");CommerceService.verifyReceipt(p);h.assertTrue(ConstructionService.structureIntact(level,lab)&&level.getEntity(lab.npc())!=null,"Original lab and Nessa retained");com.mojang.logging.LogUtils.getLogger().info("REAGENT_CROP_RESTART_PASSED: original native32essence mature provenance/canonical permanent32delivery/13earned1800XP/original lab-Nessa/receipt preserved");h.succeed();return;}h.assertTrue(track.xp()==1600&&track.completedQuestIds().size()==12,"Original12earnedAlchemyproofs are retained, not fabricated");
   var existing=ReagentCropSavedData.get(p.server).proof().save().getList("plants",net.minecraft.nbt.Tag.TAG_COMPOUND);boolean pending=false;for(var row:existing){var t=(net.minecraft.nbt.CompoundTag)row;if(t.getLong("position")==plot.asLong()&&t.getInt("age")>0)pending=true;}
   if(pending){h.assertTrue(crop.getAge(level.getBlockState(plot))>0&&ReagentCropSavedData.get(p.server).proof().count(p.getUUID())==0,"Native partial growing crop and original planter survive actual server restart");growAndHarvest();return;}
   near();level.setBlock(plot.below(),Blocks.FARMLAND.defaultBlockState().setValue(BlockStateProperties.MOISTURE,7),18);level.setBlock(plot,crop.getStateForAge(7),18);h.assertTrue(p.gameMode.destroyBlock(plot),"Private unknown mature crop can still drop ordinary resources");h.runAfterDelay(2,()->guard(()->{h.assertTrue(ReagentCropSavedData.get(p.server).proof().count(p.getUUID())==0,"No retrospective provenance from unknown planted mature crops");plant(()->{for(int n=0;n<1024&&crop.getAge(level.getBlockState(plot))==0;n++)level.getBlockState(plot).randomTick(level,plot,level.random);h.assertTrue(crop.getAge(level.getBlockState(plot))>0,"Actual registered native crop randomTick growth");p.setItemInHand(InteractionHand.MAIN_HAND,original);com.mojang.logging.LogUtils.getLogger().info("REAGENT_CROP_PENDING_PASSED: exact Mystical8.0.29/Cucumber8.0.16, unknown mature crop refusal, real consumed native seed and partial native growth/planter persisted, prior12actual proofs unchanged");h.succeed();});}));
  }
  void plant(Runnable after){near();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(seed));p.gameMode.useItemOn(p,level,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(plot.below()).add(0,.5,0),Direction.UP,plot.below(),false));h.assertTrue(p.getMainHandItem().isEmpty()&&level.getBlockState(plot).is(crop)&&crop.getAge(level.getBlockState(plot))==0,"Actual native seed use/placement consumes one seed at age0");h.runAfterDelay(2,()->guard(after));}
  void growAndHarvest(){guard(()->{near();for(int n=0;n<4096&&!crop.isMaxAge(level.getBlockState(plot));n++)level.getBlockState(plot).randomTick(level,plot,level.random);h.assertTrue(crop.isMaxAge(level.getBlockState(plot)),"Native random growth reaches actual maturity, not injected age/proof");h.assertTrue(p.gameMode.destroyBlock(plot),"Actual server-player mature native crop removal");h.runAfterDelay(2,()->guard(()->{var amount=ReagentCropSavedData.get(p.server).proof().count(p.getUUID());h.assertTrue(amount>0,"Actual native Inferium drops produce personal evidence");if(amount<32){plant(this::growAndHarvest);return;}deliver();}));});}
  void deliver(){try{p.setItemInHand(InteractionHand.MAIN_HAND,original); // Retain old held item; physical test delivery supply is separate from actual harvested-source counters.
   h.assertTrue(p.getInventory().add(new ItemStack(essence,32)),"Explicit private physical input supply fits; no crop/quest/XP proof injected");var home=lab.origin().offset(BlueprintRegistry.get(lab.blueprint(),1).rotate(BlueprintRegistry.get(lab.blueprint(),1).home(),lab.rotation()));BlacksmithRepairRuntime.near(p,home);CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)level.getEntity(lab.npc()));int before=p.getInventory().countItem(essence);var q=ProfessionService.review(p,"materials:"+ReagentCropService.QUEST);ProfessionService.confirm(p,q.nonce());h.assertTrue(p.getInventory().countItem(essence)==before-32&&CommerceService.store(p.server).professions(p.getUUID()).track(Profession.ALCHEMIST).xp()==1800,"Exact32native ingredient receipt consumed permanently for200XPonce");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("REAGENT_CROP_NATIVE_PASSED: actual Mystical8.0.29seed use/native random growth/mature real Inferium drops to32personal essence proof, restored native partial crop, exact32physical DEL/200XPonce to13earned1800XP; ordinary supplied seeds/physical inputs/randomTick timing only");h.succeed();}catch(Exception e){h.fail(e.toString());}}
 }
}
